// EditorCommon: paths, logging and small reflection / asset helpers shared by the editor build scripts
// (MASTER_PROMPT 7.1: everything is regenerated by RebuildAll; no manual editor steps). Imported from Thread.
// Every log line starts with "[BW]" so the batch logs can be grepped by Tools/unity-queue.ps1.
using System;
using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEngine;
using Object = UnityEngine.Object;

namespace Megastructure.EditorTools
{
    /// <summary>Asset paths of everything the build scripts generate or configure.</summary>
    public static class BwPaths
    {
        public const string GameRoot = "Assets/_Game";
        public const string MaterialsDir = "Assets/_Game/Materials";
        public const string SettingsDir = "Assets/_Game/Settings";
        public const string ScenesDir = "Assets/_Game/Scenes";
        public const string ShadersDir = "Assets/_Game/Shaders";
        public const string GeneratedDir = "Assets/_Game/Shaders/Generated";
        /// <summary>Generated palette include (BulwarkPalette.ToHlsl(); the path builder fixed it under Include/).</summary>
        public const string PaletteHlsl = BulwarkPalette.HlslAssetPath;
        public const string ConstantsHlsl = "Assets/_Game/Shaders/Generated/BulwarkConstGen.hlsl";
        public const string LibraryAsset = "Assets/_Game/Materials/MaterialLibrary.asset";
        public const string PaletteAsset = "Assets/_Game/Settings/BulwarkPalette.asset";
        public const string LightingAsset = "Assets/_Game/Settings/BulwarkLighting.lighting";
        public const string PanelSettingsAsset = "Assets/_Game/Settings/BwPanelSettings.asset";
        public const string ThemeAsset = "Assets/_Game/Settings/BwTheme.tss";
        public const string MainScene = "Assets/_Game/Scenes/Main.unity";
        public const string RpAsset = "Assets/Settings/PC_RPAsset.asset";
        public const string RendererAsset = "Assets/Settings/PC_Renderer.asset";
        public const string UrpGlobalSettings = "Assets/Settings/UniversalRenderPipelineGlobalSettings.asset";
        public const string DefaultVolumeProfile = "Assets/Settings/DefaultVolumeProfile.asset";
        public const string InputActions = "Assets/InputSystem_Actions.inputactions";

        public const string ProductName = "Bulwark";
        public const string CompanyName = "Megastructures";

        /// <summary>The handwritten Megastructure/Bw* shaders that exist (Part 8.6, 14.2.6); all go into Always Included Shaders.
        /// Add every new Bw* shader here (BwSea, BwFarField, ...): Validate compiles each one and checks ShaderHasError.</summary>
        public const string ShaderConcrete = "Megastructure/BwConcrete";
        public const string ShaderLine = "Megastructure/BwLine";
        public const string ShaderBeam = "Megastructure/BwBeam";
        public const string ShaderGrade = "Megastructure/BwGrade";
        static readonly string[] CoreShaderNames = { ShaderConcrete, ShaderLine, ShaderBeam, ShaderGrade };

        /// <summary>The four core shaders plus every shader under Assets/_Game/Shaders whose name starts with
        /// "Megastructure/Bw" (discovered, so parallel builders adding BwSea, BwFarField, BwSteel ... never edit this file).</summary>
        public static string[] ShaderNames
        {
            get
            {
                var list = new List<string>(CoreShaderNames);
                foreach (var guid in AssetDatabase.FindAssets("t:Shader", new[] { ShadersDir }))
                {
                    var sh = AssetDatabase.LoadAssetAtPath<Shader>(AssetDatabase.GUIDToAssetPath(guid));
                    if (sh != null && sh.name.StartsWith("Megastructure/Bw", StringComparison.Ordinal) && !list.Contains(sh.name)) list.Add(sh.name);
                }
                list.Sort(StringComparer.Ordinal);
                return list.ToArray();
            }
        }

        /// <summary>Layers of the invisible corridor colliders and safety volumes built by PathGuide (scene contract, C-18).</summary>
        public const int CorridorLayer = 30;
        public const string CorridorLayerName = "Corridor";
        public const int SafetyLayer = 31;
        public const string SafetyLayerName = "Safety";

        /// <summary>Default build output (per-owner override: environment variable BW_BUILD_DIR, lesson 3.2 #10).</summary>
        public const string DefaultBuildDir = "Builds/Bulwark";
        public const string BuildDirEnv = "BW_BUILD_DIR";

        /// <summary>Absolute project root (the folder that contains Assets/).</summary>
        public static string ProjectRoot => Path.GetDirectoryName(Application.dataPath);

        public static string Abs(string assetPath) => Path.Combine(ProjectRoot, assetPath.Replace('/', Path.DirectorySeparatorChar));
    }

    /// <summary>"[BW] ..." logging; failures carry "[BW-FAIL] " (D-06, the log-scan key of unity-queue.ps1 and run-player.ps1);
    /// problems are collected so batch methods can exit non-zero.</summary>
    public static class BwLog
    {
        public const string Prefix = "[BW] ";
        /// <summary>D-06: every failure line starts with this tag (Tools/unity-queue.ps1 counts the lines that carry it).</summary>
        public const string FailPrefix = "[BW-FAIL] ";

        /// <summary>Where error lines go (Debug.LogError). Tests swap in a capturing sink, so a unit test of the tag never
        /// writes a real [BW-FAIL] line into the test log (unity-queue counts those lines).</summary>
        public static Action<string> ErrorSink = DefaultErrorSink;
        public static void DefaultErrorSink(string line) => Debug.LogError(line);

        /// <summary>The exact failure line for a message (FailPrefix + msg).</summary>
        public static string FormatFail(string msg) => FailPrefix + msg;

        public static void Info(string msg) => Debug.Log(Prefix + msg);
        public static void Warn(string msg) => Debug.LogWarning(Prefix + "WARNING " + msg);
        /// <summary>An error line with the [BW-FAIL] tag (not recorded in a problem list).</summary>
        public static void Fail(string msg) => (ErrorSink ?? DefaultErrorSink)(FormatFail(msg));

        /// <summary>Logs a [BW-FAIL] error and records it in the problem list (may be null).</summary>
        public static void Problem(List<string> problems, string msg)
        {
            (ErrorSink ?? DefaultErrorSink)(FormatFail(msg));
            if (problems != null) problems.Add(msg);
        }

        /// <summary>Batch logs: no stack traces on plain log lines (keeps the logs readable).</summary>
        public static void QuietStackTraces()
        {
            Application.SetStackTraceLogType(LogType.Log, StackTraceLogType.None);
            Application.SetStackTraceLogType(LogType.Warning, StackTraceLogType.None);
        }
    }

    public static class EditorUtil
    {
        /// <summary>Resolves a type by full name across every loaded assembly (builders compile independently).</summary>
        public static Type FindType(string fullName)
        {
            var asms = AppDomain.CurrentDomain.GetAssemblies();
            for (int i = 0; i < asms.Length; i++)
            {
                Type t = null;
                try { t = asms[i].GetType(fullName, false); } catch { /* dynamic or broken assembly */ }
                if (t != null) return t;
            }
            return null;
        }

        /// <summary>Adds (or returns the existing) component of the named type; logs a problem if the type is missing.</summary>
        public static Component AddComponentByName(GameObject go, string fullName, List<string> problems)
        {
            var t = FindType(fullName);
            if (t == null || !typeof(Component).IsAssignableFrom(t))
            {
                BwLog.Problem(problems, $"scene: component type '{fullName}' not found (owner has not written it yet?) on '{go.name}'");
                return null;
            }
            var c = go.GetComponent(t);
            if (c == null) c = go.AddComponent(t);
            else ResetToDefaults(c);   // a reused component must not keep stale serialized values (7.1 reproducibility)
            if (c == null) BwLog.Problem(problems, $"scene: AddComponent({fullName}) failed on '{go.name}'");
            return c;
        }

        /// <summary>Resets a reused MonoBehaviour to its script defaults while keeping its identity (file ID): every visible
        /// serialized field is copied from a fresh instance on an inactive hidden GameObject (no Awake / OnEnable runs).
        /// The scene builder then sets the contract references, so an in-place RebuildAll equals a from-scratch one and a
        /// changed code default reaches Main.unity (Wave A fixes critic S3: serialized 0.08 / 120 overrode PlayerTuning).</summary>
        public static void ResetToDefaults(Component c)
        {
            if (!(c is MonoBehaviour)) return;
            var tmp = new GameObject("bw_reset_defaults") { hideFlags = HideFlags.HideAndDontSave };
            tmp.SetActive(false);
            try
            {
                var fresh = tmp.AddComponent(c.GetType());
                if (fresh == null) return;
                var src = new SerializedObject(fresh);
                var dst = new SerializedObject(c);
                var it = src.GetIterator();
                bool enter = true;
                while (it.NextVisible(enter))
                {
                    enter = false;
                    if (it.name == "m_Script" || it.name == "m_GameObject" || it.name == "m_Enabled") continue;
                    dst.CopyFromSerializedProperty(it);
                }
                dst.ApplyModifiedPropertiesWithoutUndo();
            }
            finally { Object.DestroyImmediate(tmp); }
        }

        /// <summary>Creates every missing folder of an asset path like "Assets/_Game/Materials".</summary>
        public static void EnsureFolder(string assetFolder)
        {
            assetFolder = assetFolder.TrimEnd('/');
            if (AssetDatabase.IsValidFolder(assetFolder)) return;
            int slash = assetFolder.LastIndexOf('/');
            string parent = assetFolder.Substring(0, slash);
            string leaf = assetFolder.Substring(slash + 1);
            EnsureFolder(parent);
            AssetDatabase.CreateFolder(parent, leaf);
        }

        /// <summary>The single object stored in a ProjectSettings/*.asset file (GraphicsSettings, TagManager, ...).</summary>
        public static Object LoadProjectSettingsObject(string projectSettingsPath)
        {
            var all = AssetDatabase.LoadAllAssetsAtPath(projectSettingsPath);
            return all != null && all.Length > 0 ? all[0] : null;
        }

        public static string AssetPathOf(Object o) => o != null ? AssetDatabase.GetAssetPath(o) : "";
    }
}
